using He_Thong_GYM.Models;using Microsoft.Data.SqlClient;using System.Data;
namespace He_Thong_GYM.DAL;
public sealed class LopTapDAL
{
 public async Task<List<LopTap>> LayDanhSachAsync(){const string q="SELECT l.MaLop,l.MaLopTap,l.TenLop,l.MaLoaiLop,ll.TenLoaiLop,l.MaHLV,n.HoTen,l.SucChua,l.GioBatDau,l.GioKetThuc,l.TrangThai FROM dbo.LopTap l JOIN dbo.LoaiLopTap ll ON ll.MaLoaiLop=l.MaLoaiLop JOIN dbo.HuanLuyenVien h ON h.MaHLV=l.MaHLV JOIN dbo.NhanVien n ON n.MaNV=h.MaNV ORDER BY l.MaLop DESC;";var k=new List<LopTap>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new LopTap{MaLop=r.GetInt32(0),MaLopTap=r.GetString(1),TenLop=r.GetString(2),MaLoaiLop=r.GetInt32(3),TenLoaiLop=r.GetString(4),MaHLV=r.GetInt32(5),TenHLV=r.GetString(6),SucChua=r.GetInt32(7),GioBatDau=r.GetTimeSpan(8),GioKetThuc=r.GetTimeSpan(9),TrangThai=r.GetString(10)});return k;}
 public async Task<List<(int MaLoai,string TenLoai)>> LayLoaiAsync(){var k=new List<(int,string)>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("SELECT MaLoaiLop,TenLoaiLop FROM dbo.LoaiLopTap ORDER BY TenLoaiLop",c);await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add((r.GetInt32(0),r.GetString(1)));return k;}
 public async Task ThemAsync(LopTap l){const string q="INSERT dbo.LopTap(TenLop,MaLoaiLop,MaHLV,SucChua,GioBatDau,GioKetThuc,TrangThai) VALUES(@Ten,@Loai,@HLV,@Suc,@BatDau,@KetThuc,@TrangThai);";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@Ten",l.TenLop);m.Parameters.AddWithValue("@Loai",l.MaLoaiLop);m.Parameters.AddWithValue("@HLV",l.MaHLV);m.Parameters.AddWithValue("@Suc",l.SucChua);m.Parameters.AddWithValue("@BatDau",l.GioBatDau);m.Parameters.AddWithValue("@KetThuc",l.GioKetThuc);m.Parameters.AddWithValue("@TrangThai",l.TrangThai);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task CapNhatAsync(LopTap l){const string q="UPDATE dbo.LopTap SET TenLop=@Ten,MaLoaiLop=@Loai,MaHLV=@HLV,SucChua=@Suc,GioBatDau=@BatDau,GioKetThuc=@KetThuc,TrangThai=@TrangThai WHERE MaLop=@MaLop;";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@Ten",l.TenLop);m.Parameters.AddWithValue("@Loai",l.MaLoaiLop);m.Parameters.AddWithValue("@HLV",l.MaHLV);m.Parameters.AddWithValue("@Suc",l.SucChua);m.Parameters.AddWithValue("@BatDau",l.GioBatDau);m.Parameters.AddWithValue("@KetThuc",l.GioKetThuc);m.Parameters.AddWithValue("@TrangThai",l.TrangThai);m.Parameters.AddWithValue("@MaLop",l.MaLop);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task DongLopAsync(int maLop){const string q="UPDATE dbo.LopTap SET TrangThai=N'Đã đóng' WHERE MaLop=@MaLop;";await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.AddWithValue("@MaLop",maLop);await c.OpenAsync();await m.ExecuteNonQueryAsync();}
 public async Task<List<HocVienLop>> LayHocVienAsync(int maLop,int maLichHoc){const string q="SELECT d.MaDKL,t.MaTV,t.HoTen,t.SDT,ISNULL(dd.TrangThai,N'Chưa điểm danh') FROM dbo.DangKyLop d JOIN dbo.ThanhVien t ON t.MaTV=d.MaTV LEFT JOIN dbo.DiemDanhLop dd ON dd.MaDKL=d.MaDKL AND dd.MaLichHoc=@MaLichHoc WHERE d.MaLop=@MaLop AND d.TrangThai=N'Đang tham gia' ORDER BY t.HoTen;";var k=new List<HocVienLop>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.Add("@MaLop",SqlDbType.Int).Value=maLop;m.Parameters.Add("@MaLichHoc",SqlDbType.Int).Value=maLichHoc;await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new HocVienLop{MaDKL=r.GetInt32(0),MaTV=r.GetInt32(1),HoTen=r.GetString(2),SDT=r.GetString(3),TrangThaiDiemDanh=r.GetString(4)});return k;}
 public async Task<List<BuoiHoc>> LayBuoiHocAsync(int maLop,DateTime ngay){const string q="SELECT MaLichHoc,MaLop,ThoiGianBatDau,ThoiGianKetThuc,TrangThai FROM dbo.LichHoc WHERE MaLop=@MaLop AND CAST(ThoiGianBatDau AS date)=@Ngay AND TrangThai IN(N'Đã lên lịch',N'Đã diễn ra') ORDER BY ThoiGianBatDau,MaLichHoc;";var k=new List<BuoiHoc>();await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand(q,c);m.Parameters.Add("@MaLop",SqlDbType.Int).Value=maLop;m.Parameters.Add("@Ngay",SqlDbType.Date).Value=ngay.Date;await c.OpenAsync();await using var r=await m.ExecuteReaderAsync();while(await r.ReadAsync())k.Add(new BuoiHoc{MaLichHoc=r.GetInt32(0),MaLop=r.GetInt32(1),ThoiGianBatDau=r.GetDateTime(2),ThoiGianKetThuc=r.GetDateTime(3),TrangThai=r.GetString(4)});return k;}
 public async Task<DangKyLopKetQua> DangKyLopAsync(int maTV,int maLop,int maNV){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DangKyLop",c){CommandType=CommandType.StoredProcedure};m.Parameters.AddWithValue("@MaTV",maTV);m.Parameters.AddWithValue("@MaLop",maLop);m.Parameters.AddWithValue("@VaoDanhSachCho",true);m.Parameters.AddWithValue("@MaNV",maNV);var o=m.Parameters.Add("@MaDKL",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();int? maDangKy=o.Value is DBNull or null ? null : Convert.ToInt32(o.Value);return new DangKyLopKetQua{MaDangKy=maDangKy};}
 public async Task<int> TaoBuoiHocAsync(int maLop,DateTime batDau,DateTime ketThuc,int maNV){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_TaoLichHoc",c){CommandType=CommandType.StoredProcedure};m.Parameters.Add("@MaLop",SqlDbType.Int).Value=maLop;m.Parameters.Add("@ThoiGianBatDau",SqlDbType.DateTime2).Value=batDau;m.Parameters.Add("@ThoiGianKetThuc",SqlDbType.DateTime2).Value=ketThuc;m.Parameters.Add("@MaNV",SqlDbType.Int).Value=maNV;var o=m.Parameters.Add("@MaLichHoc",SqlDbType.Int);o.Direction=ParameterDirection.Output;await c.OpenAsync();await m.ExecuteNonQueryAsync();return Convert.ToInt32(o.Value);}
 public async Task DiemDanhAsync(int maDKL,int maLichHoc,string tt,int maNV){await using var c=DbConnectionFactory.CreateConnection();await using var m=new SqlCommand("dbo.sp_DiemDanhLop",c){CommandType=CommandType.StoredProcedure};m.Parameters.Add("@MaDKL",SqlDbType.Int).Value=maDKL;m.Parameters.Add("@MaLichHoc",SqlDbType.Int).Value=maLichHoc;m.Parameters.Add("@TrangThai",SqlDbType.NVarChar,30).Value=tt;m.Parameters.Add("@MaNV",SqlDbType.Int).Value=maNV;await c.OpenAsync();await m.ExecuteNonQueryAsync();}
}
